import useDlmmPositionStore from '@/store/dlmm-position'
import usePositionStore from '@/store/position'
import { Token } from '@cetus/types'
import { Icon } from '@cetus/ui-kit'
import { cancelBubble, textEllipses } from '@cetus/utils'
import { Center, HStack, Skeleton, StackProps, Text } from '@chakra-ui/react'
import { useEffect, useState } from 'react'

function PositionCurrentPrice({
  posId,
  displayTokenA,
  displayTokenB,
  symbolEllipsesDecimals = 10, //symbol超出位数后是否展示...
  handleDirect,
  isChangeDirect = undefined,
  haveChangeIcon = true,
  wrapStyle = {
    mr: { base: '0px', lg: '4px' },
    w: { base: '100%', lg: 'unset' },
    justify: { base: 'space-between', lg: 'flex-start' },
    flexWrap: { base: 'wrap', lg: 'nowrap' }
  }
}: {
  posId: string
  displayTokenA: Token
  displayTokenB: Token
  symbolEllipsesDecimals?: number
  haveChangeIcon?: boolean
  isChangeDirect?: boolean
  handleDirect?: () => void
  wrapStyle?: StackProps
}) {
  const [isDirect, setIsDirect] = useState(true)
  const { posPoolsRelatedData } = usePositionStore()
  const { dlmmPosPoolsRelatedData } = useDlmmPositionStore()
  const currentPosPoolsRelatedData = posPoolsRelatedData[posId] || dlmmPosPoolsRelatedData[posId]

  useEffect(() => {
    if (typeof isChangeDirect == 'boolean') {
      setIsDirect(!isDirect)
    }
  }, [isChangeDirect])
  return (
    <HStack
      {...wrapStyle}
      cursor={haveChangeIcon ? 'pointer' : 'default'}
      onClick={(e: any) => {
        cancelBubble(e)
        if (haveChangeIcon) {
          setIsDirect(!isDirect)
          if (handleDirect) {
            handleDirect()
          }
        }
      }}
      sx={{
        '&:hover .swap_icon svg ': {
          fill: 'text_caption'
        }
      }}
    >
      <Text color="primary_gray">Current Pool Price</Text>

      <HStack>
        <Skeleton isLoaded={!!currentPosPoolsRelatedData?.currentPrice}>
          <Text color="text_caption" maxW="200px" wordBreak="break-all" whiteSpace="nowrap">
            {isDirect ? currentPosPoolsRelatedData?.currentPrice : currentPosPoolsRelatedData?.currentPriceReverse}
          </Text>
        </Skeleton>
        <HStack gap="0">
          {currentPosPoolsRelatedData?.currentPrice && (
            <HStack gap="0" flexWrap="nowrap">
              <Text color="primary_gray" whiteSpace="nowrap">
                {textEllipses(isDirect ? displayTokenB?.symbol : displayTokenA?.symbol, symbolEllipsesDecimals)}
              </Text>
              <Text color="primary_gray">/</Text>
              <Text color="primary_gray" whiteSpace="nowrap">
                {textEllipses(isDirect ? displayTokenA?.symbol : displayTokenB?.symbol, symbolEllipsesDecimals)}
              </Text>
            </HStack>
          )}
          {haveChangeIcon && (
            <Center w="32px" h="32px">
              <Icon className="swap_icon" xlinkHref="#icon-icon_swap1" w="16px" h="16px" />
            </Center>
          )}
        </HStack>
      </HStack>
    </HStack>
  )
}

export default PositionCurrentPrice
